const H = 4.0, DEP = 4.0;          // 128 (height, world Y) and 128 (width, receding Z)
const INX = -5.2, OUTX = 5.2;
const IN_T = 0.75;                 // 3 channels
const BLACK = 0x000000, ORANGE = 0xE8710A, BLUE = 0x2C6FBB;
const CH = [0xE8710A, 0xF4A259, 0xA94E00];

const tOf = K => 0.75 + 1.15 * Math.log(K / 3) / Math.log(32);

/* shared materials */
