const slabMat  = new THREE.MeshBasicMaterial({ color: 0xffffff, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
const dotMat   = new THREE.MeshBasicMaterial({ color: BLACK });
const strokeMat= new THREE.MeshBasicMaterial({ color: BLACK });
const fillMat  = new THREE.MeshBasicMaterial({ color: 0xffffff });
