const spMat    = new THREE.MeshBasicMaterial({ color: BLUE,   transparent: true, opacity: 0.22, depthWrite: false });
const invisMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
const dimList  = [lineMat, strokeMat];

function disposeGroup(g){
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i];
    c.traverse?.(o => o.geometry?.dispose?.());
    g.remove(c);
  }
}

/* ── thick 2D stroke helper (quad strip per edge, square caps fill the joins) */
function strokeGeom(pts, closed, w){
  const hw = w / 2, pos = [], n = pts.length;
  const lim = closed ? n : n - 1;
  for (let i = 0; i < lim; i++){
    const a = pts[i], b = pts[(i + 1) % n];
    let dx = b.x - a.x, dy = b.y - a.y;
    const L = Math.hypot(dx, dy); if (L < 1e-9) continue;
    dx /= L; dy /= L;
    const nx = -dy * hw, ny = dx * hw;
    const ax = a.x - dx * hw, ay = a.y - dy * hw, bx = b.x + dx * hw, by = b.y + dy * hw;
    const p = [[ax+nx,ay+ny],[bx+nx,by+ny],[bx-nx,by-ny],[ax-nx,ay-ny]];
    pos.push(p[0][0],p[0][1],0, p[1][0],p[1][1],0, p[2][0],p[2][1],0,
             p[0][0],p[0][1],0, p[2][0],p[2][1],0, p[3][0],p[3][1],0);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return g;
}
function roundedRectPts(w, h, r, seg){
  const pts = [], hx = w/2 - r, hy = h/2 - r;
  const corners = [[hx,hy,0],[-hx,hy,Math.PI/2],[-hx,-hy,Math.PI],[hx,-hy,-Math.PI/2]];
  for (const [cx, cy, a0] of corners)
    for (let i = 0; i <= seg; i++){
      const a = a0 + i / seg * Math.PI / 2;
      pts.push(new THREE.Vector2(cx + r*Math.cos(a), cy + r*Math.sin(a)));
    }
  return pts;
}
function outlinedShape(pts, strokeW, z){
  const g = new THREE.Group();
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape(pts)), fillMat);
  fill.position.z = z - 0.005;
  g.add(fill);
  g.add(new THREE.Mesh(strokeGeom(pts, true, strokeW), strokeMat));
  return g;
}

