    const m = new THREE.Mesh(new THREE.CircleGeometry(0.045, 14), dotMat);
    if (mode === 'top'){ m.rotation.x = -Math.PI/2; m.position.set(x + i*0.15, H/2 + 0.012, 0.35); }
    else               { m.position.set(x + i*0.15, -0.95, DEP/2 + 0.012); }
    group.add(m);
  }
