function buildSlab(group, cx, t, nVis, skips, withDots){
  disposeGroup(group);
  const x0 = cx - t/2, step = t / nVis;
  const box = new THREE.Mesh(new THREE.BoxGeometry(t, H, DEP), slabMat);
  box.position.set(cx, 0, 0);
  group.add(box);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(box.geometry), lineMat);
  edges.position.copy(box.position);
  group.add(edges);

  const segs = [];
  for (let i = 1; i < nVis; i++){
    if (skips.indexOf(i) >= 0) continue;
    const x = x0 + i * step;
    segs.push(x, H/2 + 0.006, -DEP/2,  x, H/2 + 0.006, DEP/2);     // top receding face
    segs.push(x, -H/2, DEP/2 + 0.006,  x, H/2, DEP/2 + 0.006);     // front face
  }
  if (segs.length){
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(segs, 3));
    group.add(new THREE.LineSegments(g, lineMat));
  }
  if (withDots){
    addDots(group, x0 + 4 * step, 'front');
    addDots(group, x0 + 8 * step, 'top');
  }
}

