  info.innerHTML = `Each filter: 3&times;3&times;3 = <b>27</b> weights<br>` +
                   `Bank: ${K} &times; 27 = <b>${K * 27}</b> parameters` +
                   (selFilter >= 0 ? `<br>Selected filter #${selFilter + 1} of ${K}` : '');
}
function setK(k, fromSlider){
  K = Math.max(3, Math.min(96, Math.round(k)));
  tgtT = tOf(K);
  if (!fromSlider) slider.value = K;
  kVal.textContent = K;
  lblK.div.innerHTML = num(String(K));
  lblHeadOut.div.innerHTML = mathOut(K);
  if (selFilter >= K) selFilter = K - 1;
  rebuildOutput();
  updateInfo();
}
function setEmphasis(mode){
  emphasis = (mode === 'Spatial view' || mode === 'spatial') ? 'spatial' : 'channel';
  btnCh.classList.toggle('active', emphasis === 'channel');
  btnSp.classList.toggle('active', emphasis === 'spatial');
  applyEmphasis();
}
function selectFilter(f){
  selFilter = Math.max(0, Math.min(K - 1, Math.floor(f)));
  lblKernel.div.style.visibility = 'visible';
  applySelection();
  updateInfo();
}
function clearSelection(){
  selFilter = -1;
  lblKernel.div.style.visibility = 'hidden';
  applySelection();
  updateInfo();
}

slider.addEventListener('input', () => setK(+slider.value, true));
btnCh.addEventListener('click', () => setEmphasis('channel'));
btnSp.addEventListener('click', () => setEmphasis('spatial'));
btnFil.addEventListener('click', () => selectFilter(selFilter < 0 ? Math.floor(K/2) : (selFilter + 1) % K));
btnClr.addEventListener('click', clearSelection);

/* click picking on the filter bank */
registerInteractive(filterProxy, {
  title: 'Filter bank',
  tooltip: 'Click to select one filter (3×3×3 = 27 weights)',
  body: 'Each filter in the bank is a 3×3 kernel for EVERY input channel: 3·3·3 = 27 weights. One filter produces exactly one output channel, so K filters give K output channels.',
  onClick: (hit) => {
    const u = (hit.point.x + 2.2) / 4.4;
    selectFilter(Math.max(0, Math.min(K - 1, Math.floor(u * K))));
  }
});
registerInteractive(inputProxy, {
  title: 'x_in ∈ ℝ³ˣ¹²⁸ˣ¹²⁸',
  tooltip: 'Input tensor: 3 channel sheets of 128×128',
  body: '3 channels (e.g. R,G,B), each a 128×128 image plane. The slab is thin because the channel dimension is only 3.'
});
registerInteractive(outputProxy, {
  title: 'x_out ∈ ℝ^{K×128×128}',
  tooltip: 'Output tensor: one 128×128 sheet per filter',
  body: 'Every filter writes one 128×128 output channel, so the slab thickness tracks the filter count while the 128×128 face is unchanged.'
});

/* ── demo steps ──────────────────────────────────────────────────────────── */
const steps = [
  { title: 'The input tensor', narration: 'Three channel sheets, each a 128×128 image plane, stacked into a thin slab: x_in ∈ ℝ³ˣ¹²⁸ˣ¹²⁸.',
    state: { filterCount: 3, viewEmphasis: 'Channel view' }, select: false },
  { title: 'One filter, 27 weights', narration: 'A filter spans ALL input channels: its three 3×3 kernel slices highlight together with all three input sheets, and it writes exactly one output sheet. 3×3×3 = 27 parameters.',
    state: { filterCount: 3, viewEmphasis: 'Channel view' }, select: true },
  { title: 'Growing the bank to 96 filters', narration: 'The output slab thickens and its label climbs to 96. Filter count IS output-channel count: 96 × 27 = 2592 parameters.',
    state: { filterCount: 96, viewEmphasis: 'Channel view' }, select: false },
  { title: 'Spatial size is untouched', narration: 'Spatial view shades the 128×128 faces: both slabs keep them. The layer remaps channels (3 → 96) while preserving spatial resolution.',
    state: { filterCount: 96, viewEmphasis: 'Spatial view' }, select: false }
];
let stepIdx = -1;
function goToStep(i){
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  setK(s.state.filterCount);
  setEmphasis(s.state.viewEmphasis);
  if (s.select) selectFilter(Math.floor(K / 2)); else clearSelection();
  stepTitle.textContent = `${stepIdx + 1}/${steps.length} · ${s.title}`;
  stepNarr.textContent = s.narration;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── thickness tween (own ticker; the scaffold loop stays untouched) ──────── */
function tick(){
  requestAnimationFrame(tick);
  if (Math.abs(curT - tgtT) > 0.003){
    curT += (tgtT - curT) * 0.22;
    outputProxy.scale.x = curT;
    lbl128R.pos.set(OUTX + curT/2, 0.7, -DEP/2);
    lbl128B.pos.set(OUTX + curT/2, -H/2, -0.7);
    rebuildOutput();
  } else if (curT !== tgtT){
    curT = tgtT;
    outputProxy.scale.x = curT;
    lbl128R.pos.set(OUTX + curT/2, 0.7, -DEP/2);
    lbl128B.pos.set(OUTX + curT/2, -H/2, -0.7);
    rebuildOutput();
  }
}
tick();

setEmphasis('Channel view');
setK(96);
updateInfo();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

