   output slab x_out  → BoxGeometry(t(K), 4, 4) white + edges, ≤11 divider lines
   ellipsis '...'     → 3 × SphereGeometry(0.085) black, in the two skipped divider gaps
   block arrows ×2    → stroked 7-point polygon (DoubleSide quad strip + Line loop) + white fill
   filter bank box    → stroked rounded rect (w4.4 h1.9 r0.35) + white ShapeGeometry fill
   kernel overlay     → 27 × BoxGeometry(0.2) in 3 slices + black EdgesGeometry
   sheet highlights   → BoxGeometry overlays, transparent orange / channel colors
   emphasis washes    → PlaneGeometry (top+front = channel, +X face = spatial) — OPT-IN
   link lines         → dashed Line (orange)
   all text           → addLabel HTML overlays
   ─────────────────────────────────────────────────────────────────────────── */

const H = 4.0, DEP = 4.0;          // 128 (height, world Y) and 128 (width, receding Z)
const INX = -5.2, OUTX = 5.4;
const IN_T = 0.60;                 // 3 channels — deliberately thin
const BLACK = 0x000000, ORANGE = 0xE8710A, BLUE = 0x2C6FBB;
const CH = [0xE8710A, 0xF4A259, 0xA94E00];

// exaggerated channel-growth: K=3 → 0.60, K=96 → 2.80  (≈4.7× thicker)
const tOf = K => 0.60 + 2.20 * Math.log(K / 3) / Math.log(32);

/* shared materials */
const lineMat   = new THREE.LineBasicMaterial({ color: BLACK });
const slabMat   = new THREE.MeshBasicMaterial({ color: 0xffffff, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
const dotMat    = new THREE.MeshBasicMaterial({ color: BLACK });
const strokeMat = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide });
const fillMat   = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });
const chMat     = new THREE.MeshBasicMaterial({ color: ORANGE, transparent: true, opacity: 0.17, depthWrite: false });
const spMat     = new THREE.MeshBasicMaterial({ color: BLUE,   transparent: true, opacity: 0.22, depthWrite: false });
const invisMat  = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
const dimList   = [lineMat, strokeMat];

function disposeGroup(g){
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i];
    c.traverse?.(o => o.geometry?.dispose?.());
    g.remove(c);
  }
}

/* ── thick 2D stroke helper (quad strip per edge, square caps fill the joins) */
function strokeGeom(pts, closed, w){
  const hw = w / 2, pos = [], n = pts.length;
  const lim = closed ? n : n - 1;
  for (let i = 0; i < lim; i++){
    const a = pts[i], b = pts[(i + 1) % n];
    let dx = b.x - a.x, dy = b.y - a.y;
    const L = Math.hypot(dx, dy); if (L < 1e-9) continue;
    dx /= L; dy /= L;
    const nx = -dy * hw, ny = dx * hw;
    const ax = a.x - dx * hw, ay = a.y - dy * hw, bx = b.x + dx * hw, by = b.y + dy * hw;
    const p = [[ax+nx,ay+ny],[bx+nx,by+ny],[bx-nx,by-ny],[ax-nx,ay-ny]];
    pos.push(p[0][0],p[0][1],0, p[1][0],p[1][1],0, p[2][0],p[2][1],0,
             p[0][0],p[0][1],0, p[2][0],p[2][1],0, p[3][0],p[3][1],0);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return g;
}
function roundedRectPts(w, h, r, seg){
  const pts = [], hx = w/2 - r, hy = h/2 - r;
  const corners = [[hx,hy,0],[-hx,hy,Math.PI/2],[-hx,-hy,Math.PI],[hx,-hy,-Math.PI/2]];
  for (const [cx, cy, a0] of corners)
    for (let i = 0; i <= seg; i++){
      const a = a0 + i / seg * Math.PI / 2;
      pts.push(new THREE.Vector2(cx + r*Math.cos(a), cy + r*Math.sin(a)));
    }
  return pts;
}
/* white fill + thick DoubleSide stroke ribbon + a plain Line loop as a guarantee */
function outlinedShape(pts, strokeW, z){
  const g = new THREE.Group();
  const fill = new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape(pts)), fillMat);
  fill.position.z = z - 0.01;
  g.add(fill);
  const ribbon = new THREE.Mesh(strokeGeom(pts, true, strokeW), strokeMat);
  ribbon.position.z = z;
  g.add(ribbon);
  const loopPts = pts.map(p => new THREE.Vector3(p.x, p.y, z + 0.002));
  loopPts.push(loopPts[0].clone());
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(loopPts), lineMat));
  return g;
}

/* ── slabs ───────────────────────────────────────────────────────────────── */
const inputGroup  = new THREE.Group(); scene.add(inputGroup);
const outputGroup = new THREE.Group(); scene.add(outputGroup);
const empGroup    = new THREE.Group(); scene.add(empGroup);
const selGroup    = new THREE.Group(); scene.add(selGroup);

function addDots(group, x, mode){
  for (let i = -1; i <= 1; i++){
    const m = new THREE.Mesh(new THREE.SphereGeometry(0.085, 12, 10), dotMat);
    if (mode === 'top') m.position.set(x, H/2 + 0.07, 0.15 + i * 0.28);
    else                m.position.set(x + i * 0.28, -1.0, DEP/2 + 0.07);
    group.add(m);
  }
}

function buildSlab(group, cx, t, nVis, skips, withDots){
  disposeGroup(group);
  const x0 = cx - t/2, step = t / nVis;
  const box = new THREE.Mesh(new THREE.BoxGeometry(t, H, DEP), slabMat);
  box.position.set(cx, 0, 0);
  group.add(box);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(box.geometry), lineMat);
  edges.position.copy(box.position);
  group.add(edges);

  const segs = [];
  for (let i = 1; i < nVis; i++){
    if (skips.indexOf(i) >= 0) continue;
    const x = x0 + i * step;
    segs.push(x, H/2 + 0.006, -DEP/2,  x, H/2 + 0.006, DEP/2);     // top receding face
    segs.push(x, -H/2, DEP/2 + 0.006,  x, H/2, DEP/2 + 0.006);     // front face
  }
  if (segs.length){
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(segs, 3));
    group.add(new THREE.LineSegments(g, lineMat));
  }
  if (withDots){
    addDots(group, x0 + 4 * step, 'front');   // gap left by the skipped divider #4
    addDots(group, x0 + 8 * step, 'top');     // gap left by the skipped divider #8
  }
}

function layout(K){
  const nVis = Math.min(K, 12);
  return { nVis, skips: K > nVis ? [4, 8] : [] };
}

/* ── state ───────────────────────────────────────────────────────────────── */
let K = 96, curT = tOf(96), tgtT = tOf(96);
let emphasis = 'none';           // line-art by default, matching the source
let selFilter = -1;

buildSlab(inputGroup, INX, IN_T, 3, [], false);

function applyEmphasis(){
  disposeGroup(empGroup);
  if (emphasis === 'none') return;
  const slabs = [[INX, IN_T], [OUTX, curT]];
  for (const [cx, t] of slabs){
    if (emphasis === 'channel'){
      const top = new THREE.Mesh(new THREE.PlaneGeometry(t, DEP), chMat);
      top.rotation.x = -Math.PI/2; top.position.set(cx, H/2 + 0.004, 0);
      empGroup.add(top);
      const front = new THREE.Mesh(new THREE.PlaneGeometry(t, H), chMat);
      front.position.set(cx, 0, DEP/2 + 0.004);
      empGroup.add(front);
    } else {
      const side = new THREE.Mesh(new THREE.PlaneGeometry(DEP, H), spMat);
      side.rotation.y = Math.PI/2; side.position.set(cx + t/2 + 0.004, 0, 0);
      empGroup.add(side);
    }
  }
}

function setDim(on){
  for (const m of dimList){ m.transparent = on; m.opacity = on ? 0.32 : 1; m.needsUpdate = true; }
}

function applySelection(){
  disposeGroup(selGroup);
  if (selFilter < 0){ setDim(false); return; }
  setDim(true);

  /* the 3 input channel sheets this filter reads */
  for (let i = 0; i < 3; i++){
    const w = IN_T / 3, x = INX - IN_T/2 + i*w + w/2;
    const m = new THREE.Mesh(new THREE.BoxGeometry(w*0.96, H*1.012, DEP*1.012),
      new THREE.MeshBasicMaterial({ color: CH[i], transparent: true, opacity: 0.4, depthWrite: false }));
    m.position.set(x, 0, 0);
    selGroup.add(m);
  }
  /* the single output sheet it writes */
  const { nVis } = layout(K);
  const step = curT / nVis;
  const vs = Math.min(nVis - 1, Math.floor(selFilter / K * nVis));
  const ox = OUTX - curT/2 + vs*step + step/2;
  const om = new THREE.Mesh(new THREE.BoxGeometry(Math.max(step*0.9, 0.07), H*1.012, DEP*1.012),
    new THREE.MeshBasicMaterial({ color: ORANGE, transparent: true, opacity: 0.5, depthWrite: false }));
  om.position.set(ox, 0, 0);
  selGroup.add(om);

  /* 3×3×3 kernel stack above the filter box */
  const KX = 0, KY = 1.70, KZ = 0.6;
  for (let s = 0; s < 3; s++){
    for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++){
      const g = new THREE.BoxGeometry(0.2, 0.2, 0.2);
      const cube = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color: CH[s], transparent: true, opacity: 0.85 }));
      cube.position.set(KX + (c-1)*0.24, KY + (1-r)*0.24, KZ + (s-1)*0.45);
      selGroup.add(cube);
      const e = new THREE.LineSegments(new THREE.EdgesGeometry(g), new THREE.LineBasicMaterial({ color: BLACK }));
      e.position.copy(cube.position);
      selGroup.add(e);
    }
  }
  /* dashed links: input sheets → kernel → output sheet */
  const dmat = new THREE.LineDashedMaterial({ color: ORANGE, dashSize: 0.16, gapSize: 0.12 });
  const mk = (a, b) => {
    const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), dmat);
    l.computeLineDistances(); selGroup.add(l);
  };
  mk(new THREE.Vector3(INX + IN_T/2, H/2 + 0.1, 0), new THREE.Vector3(-0.55, KY + 0.15, KZ));
  mk(new THREE.Vector3(0.55, KY + 0.15, KZ), new THREE.Vector3(ox, H/2 + 0.1, 0));
}

function rebuildOutput(){
  const { nVis, skips } = layout(K);
  buildSlab(outputGroup, OUTX, curT, nVis, skips, K > nVis);
  applyEmphasis();
  if (selFilter >= 0) applySelection();
}
rebuildOutput();

/* ── arrows + filter bank box ────────────────────────────────────────────── */
function blockArrow(cx, cy){
  const p = [ [-0.75,0.275], [0.15,0.275], [0.15,0.55], [0.75,0], [0.15,-0.55], [0.15,-0.275], [-0.75,-0.275] ]
    .map(v => new THREE.Vector2(v[0], v[1]));
  const g = outlinedShape(p, 0.06, 0);
  g.position.set(cx, cy, 0);
  scene.add(g);
  return g;
}
blockArrow(-2.6, -0.15);
blockArrow( 2.7, -0.15);

const boxPts = roundedRectPts(4.4, 1.9, 0.35, 6);
const filterBox = outlinedShape(boxPts, 0.085, 0);
scene.add(filterBox);

/* ── invisible pick proxies (persistent, so hit-testing survives rebuilds) ── */
const filterProxy = new THREE.Mesh(new THREE.PlaneGeometry(4.4, 1.9), invisMat);
filterProxy.position.set(0, 0, 0.05);
scene.add(filterProxy);
const inputProxy = new THREE.Mesh(new THREE.BoxGeometry(IN_T, H, DEP), invisMat);
inputProxy.position.set(INX, 0, 0);
scene.add(inputProxy);
const outputProxy = new THREE.Mesh(new THREE.BoxGeometry(1, H, DEP), invisMat);
outputProxy.position.set(OUTX, 0, 0);
outputProxy.scale.x = curT;
scene.add(outputProxy);

/* ── camera (after all geometry) ─────────────────────────────────────────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.85 });
controls.minAzimuthAngle = THREE.MathUtils.degToRad(-25);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(25);
controls.minPolarAngle   = Math.PI/2 - THREE.MathUtils.degToRad(20);
controls.maxPolarAngle   = Math.PI/2 + THREE.MathUtils.degToRad(20);
controls.enablePan = false;

/* ── labels ──────────────────────────────────────────────────────────────── */
const SER = "font-family:Georgia,'Times New Roman',serif";
const mathIn  = `<span style="${SER}"><b>x</b><sub>in</sub> &isin; &#8477;<sup>3&times;128&times;128</sup></span>`;
const mathOut = k => `<span style="${SER}"><b>x</b><sub>out</sub> &isin; &#8477;<sup>${k}&times;128&times;128</sup></span>`;
const num = s => `<span style="${SER}">${s}</span>`;

addLabel(mathIn, new THREE.Vector3(-5.4, 3.5, 0), { fontSize: '18px' });
const lblHeadOut = addLabel(mathOut(96), new THREE.Vector3(5.4, 3.5, 0), { fontSize: '18px' });

addLabel(num('128'), new THREE.Vector3(INX - IN_T/2, 0, DEP/2),   { fontSize: '19px', offset: [-30, 0] });
addLabel(num('128'), new THREE.Vector3(INX - IN_T/2, H/2, 1.15),  { fontSize: '19px', offset: [-26, -12] });
addLabel(num('3'),   new THREE.Vector3(INX, -H/2 - 0.45, DEP/2),  { fontSize: '19px', offset: [0, 14] });

const lblK    = addLabel(num('96'),  new THREE.Vector3(OUTX, -H/2 - 0.45, DEP/2), { fontSize: '19px', offset: [0, 14] });
const lbl128R = addLabel(num('128'), new THREE.Vector3(OUTX + curT/2, 0.8, -DEP/2), { fontSize: '19px', offset: [30, 0] });
const lbl128B = addLabel(num('128'), new THREE.Vector3(OUTX + curT/2, -H/2, -0.8),  { fontSize: '19px', offset: [30, 16] });

addLabel(`<span style="${SER}">Filter Bank with</span>`, new THREE.Vector3(0, 0.33, 0.06), { fontSize: '19px' });
addLabel(`<span style="${SER}">3x3 filters</span>`,      new THREE.Vector3(0, -0.34, 0.06), { fontSize: '19px' });

const lblKernel = addLabel('one filter &middot; 3&times;3&times;3 = 27 weights',
  new THREE.Vector3(0, 2.55, 0.6), { fontSize: '12px', color: '#A94E00', bold: true });
lblKernel.div.style.visibility = 'hidden';

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const slider  = document.getElementById('filterCount');
const kVal    = document.getElementById('kVal');
const btnNo   = document.getElementById('btnNone');
const btnCh   = document.getElementById('btnChannel');
const btnSp   = document.getElementById('btnSpatial');
const btnFil  = document.getElementById('btnFilter');
const btnClr  = document.getElementById('btnClear');
const info    = document.getElementById('paramInfo');
const stepTitle = document.getElementById('stepTitle');
const stepNarr  = document.getElementById('stepNarr');

function updateInfo(){
  info.innerHTML = `Each filter: 3&times;3&times;3 = <b>27</b> weights<br>` +
                   `Bank: ${K} &times; 27 = <b>${K * 27}</b> parameters` +
                   (selFilter >= 0 ? `<br>Selected filter #${selFilter + 1} of ${K}` : '');
}
function setK(k, fromSlider){
  K = Math.max(3, Math.min(96, Math.round(k)));
  tgtT = tOf(K);
  if (!fromSlider) slider.value = K;
  kVal.textContent = K;
  lblK.div.innerHTML = num(String(K));
  lblHeadOut.div.innerHTML = mathOut(K);
  if (selFilter >= K) selFilter = K - 1;
  rebuildOutput();
  updateInfo();
}
function setEmphasis(mode){
  const m = String(mode).toLowerCase();
  emphasis = m.indexOf('spatial') >= 0 ? 'spatial'
           : m.indexOf('channel') >= 0 ? 'channel' : 'none';
  btnNo.classList.toggle('active', emphasis === 'none');
  btnCh.classList.toggle('active', emphasis === 'channel');
  btnSp.classList.toggle('active', emphasis === 'spatial');
  applyEmphasis();
}
function selectFilter(f){
  selFilter = Math.max(0, Math.min(K - 1, Math.floor(f)));
  lblKernel.div.style.visibility = 'visible';
  applySelection();
  updateInfo();
}
function clearSelection(){
  selFilter = -1;
  lblKernel.div.style.visibility = 'hidden';
  applySelection();
  updateInfo();
}

slider.addEventListener('input', () => setK(+slider.value, true));
btnNo.addEventListener('click', () => setEmphasis('none'));
btnCh.addEventListener('click', () => setEmphasis('channel'));
btnSp.addEventListener('click', () => setEmphasis('spatial'));
btnFil.addEventListener('click', () => selectFilter(selFilter < 0 ? Math.floor(K/2) : (selFilter + 1) % K));
btnClr.addEventListener('click', clearSelection);

/* click picking on the filter bank */
registerInteractive(filterProxy, {
  title: 'Filter bank',
  tooltip: 'Click to select one filter (3×3×3 = 27 weights)',
  body: 'Each filter in the bank is a 3×3 kernel for EVERY input channel: 3·3·3 = 27 weights. One filter produces exactly one output channel, so K filters give K output channels.',
  onClick: (hit) => {
    const u = (hit.point.x + 2.2) / 4.4;
    selectFilter(Math.max(0, Math.min(K - 1, Math.floor(u * K))));
  }
});
registerInteractive(inputProxy, {
  title: 'x_in ∈ ℝ³ˣ¹²⁸ˣ¹²⁸',
  tooltip: 'Input tensor: 3 channel sheets of 128×128',
  body: '3 channels (e.g. R,G,B), each a 128×128 image plane. The slab is thin because the channel dimension is only 3.'
});
registerInteractive(outputProxy, {
  title: 'x_out ∈ ℝ^{K×128×128}',
  tooltip: 'Output tensor: one 128×128 sheet per filter',
  body: 'Every filter writes one 128×128 output channel, so the slab thickness tracks the filter count while the 128×128 face is unchanged.'
});

/* ── demo steps ──────────────────────────────────────────────────────────── */
const steps = [
  { title: 'The input tensor', narration: 'Three channel sheets, each a 128×128 image plane, stacked into a thin slab: x_in ∈ ℝ³ˣ¹²⁸ˣ¹²⁸.',
    state: { filterCount: 3, viewEmphasis: 'none' }, select: false },
  { title: 'One filter, 27 weights', narration: 'A filter spans ALL input channels: its three 3×3 kernel slices highlight together with all three input sheets, and it writes exactly one output sheet. 3×3×3 = 27 parameters.',
    state: { filterCount: 3, viewEmphasis: 'Channel view' }, select: true },
  { title: 'Growing the bank to 96 filters', narration: 'The output slab thickens and its label climbs to 96. Filter count IS output-channel count: 96 × 27 = 2592 parameters.',
    state: { filterCount: 96, viewEmphasis: 'Channel view' }, select: false },
  { title: 'Spatial size is untouched', narration: 'Spatial view shades the 128×128 faces: both slabs keep them. The layer remaps channels (3 → 96) while preserving spatial resolution.',
    state: { filterCount: 96, viewEmphasis: 'Spatial view' }, select: false }
];
let stepIdx = -1;
function goToStep(i){
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  setK(s.state.filterCount);
  setEmphasis(s.state.viewEmphasis);
  if (s.select) selectFilter(Math.floor(K / 2)); else clearSelection();
  stepTitle.textContent = `${stepIdx + 1}/${steps.length} · ${s.title}`;
  stepNarr.textContent = s.narration;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── thickness tween (own ticker; the scaffold loop stays untouched) ──────── */
function syncOutputLabels(){
  outputProxy.scale.x = curT;
  lbl128R.pos.set(OUTX + curT/2, 0.8, -DEP/2);
  lbl128B.pos.set(OUTX + curT/2, -H/2, -0.8);
}
function tick(){
  requestAnimationFrame(tick);
  if (Math.abs(curT - tgtT) > 0.003){
    curT += (tgtT - curT) * 0.22;
    syncOutputLabels();
    rebuildOutput();
  } else if (curT !== tgtT){
    curT = tgtT;
    syncOutputLabels();
    rebuildOutput();
  }
}
tick();

setEmphasis('none');
setK(96);
updateInfo();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

